claims=[];items=[];problems=[];readings=[]
def item(n,title,source,scans,lines,statement):
 items.append(dict(id=f'SA23-{n}',sources=[source],kind='additional source subject',cote=['21' if 'K21' in source else '1'],scans=[scans],lines=lines,his_words=title,statement=statement,reconstruction='See individual claim records; no prior indexed-note verdict is created for this successor assignment.',check='additional subject',check_reason='Full supplied transcription read; source qualifications preserved.'))
def claim(n,item,title,source,scans,lines,words,statement,check,page='argument supplied'):
 claims.append(dict(id=f'C-SA23-analysis_curves-{n:03}',items=[f'SA23-{item}'],title=title,source='sources/texts/codex/'+source+'_transcription.tex',cote='21' if source.startswith('K21') else '1',scans=scans,lines=lines,his_statement=words,statement=statement,status_on_pages=page,present_status=check,classification='PENDING',fate='Literature mapping in progress; this incremental record is not a final novelty verdict.',refs=[],author='Archival working hand; no printed byline or calendar date on these supplied leaves',present_status_date='2026-11-19'))
def problem(n,title,ids,words,modern,why):
 problems.append(dict(id=f'MP-SA23-analysis_curves-{n:02}',title=title,claims=[f'C-SA23-analysis_curves-{i:03}' for i in ids],as_he_states=words,plausible_today=modern,why_open=why,state_of_art='Literature mapping in progress',worth='Source-level clarification and exact theorem comparison',refs=[],date='2026-11-19'))
def reading(cote,scan,line,reading,alternative,evidence,weight='substantive'):
 readings.append(dict(cote=cote,scan=scan,line=line,reading=reading,alternative=alternative,evidence=evidence,weight=weight,confidence='mathematical alarm high; ink unavailable'))
item(401,'Generator tests for bounded cohomological functors','K21-01','4–6','13–74','Finite filtrations reduce vanishing to a detecting family; support and ample twists give examples.')
claim(1,401,'Finite-filtration and noetherian detection','K21-01','4–5','13–33','suite de composition finie; système de générateurs','A family whose quotients finitely filter every object detects vanishing of right-exact functors and bounded-above cohomological functors; dual statement detects bounded-below contravariant functors. In a noetherian abelian category weak detection Hom(G,F)≠0 for some G whenever F≠0 gives the required finite filtration.','The maximal-subobject argument and descending induction are valid. The displayed definition accidentally quantifies M∈C rather than M∈G; the proof uses G. Boundedness is essential for the induction.')
claim(2,401,'Support detects the zero functor','K21-01','5','35–52','Ass Hom(M,F)=supp M ∩ Ass F','For noetherian A and finite modules Mi supported on V(I), their union of supports equals V(I) iff Hom(Mi,F) jointly detects nonzero I-torsion modules. Finite I-torsion modules then have filtrations by quotients of Mi.','Uses Ass Hom(M,F)=Supp(M)∩Ass(F), with M finite and F arbitrary. This is a weak detecting family, not the usual categorical generator whose Hom functor is faithful: over k[ε]/ε² the module k detects every nonzero finite module but cannot surject onto A.')
claim(3,401,'Ample negative twists form detecting families','K21-01','5–6','54–74','Mi(-n), n>N','For noetherian X with ample invertible O(1), coherent Mi whose supports cover Y give weak detection on quasi-coherent modules supported on Y via all Mi(-n), n>N.','Choose affine nonzero internal Hom, then a sufficiently positive twist has a nonzero global section. The source’s sign ambiguity is resolved by the actual displayed Hom calculation, not by altering the transcription.')
item(402,'Tensor and Hom valued in abelian categories','K21-01','6–9','76–231','Abstract tensor objects unify covariant and contravariant module-functor representation.')
claim(4,402,'Tensor object in an abelian category','K21-01','6–8','76–179','Hom(P⊗A M,Q)=HomA(M,Hom(P,Q))','For a right A-object P in an abelian category, P⊗A M exists for finitely presented left modules M; arbitrary M are allowed if coproducts exist. It is right exact and preserves colimits whenever the specified objects exist. The opposite-category construction gives internal Hom.','The finite presentation construction by cokernel is valid and presentation independent by the displayed representing property; the existence qualifications must remain.')
claim(5,402,'Finite-presentation Eilenberg–Watts equivalence','K21-01','8','181–209','T(A)⊗A M → T(M)','For additive T from finite A-modules, with A noetherian, the canonical natural map is an isomorphism for all M iff T is right exact. Evaluation at A gives equivalence with A-objects. For all modules add preservation of arbitrary coproducts.','Checked from a finite free presentation. The all-module version really needs the added coproduct condition; right exactness alone is insufficient.')
claim(6,402,'Contravariant module-functor representation','K21-01','9','215–231','T(M) → HomA(M,T(A))','A contravariant additive left-exact functor on finitely presented modules is represented in the target category by T(A). For all modules its extension must convert direct sums into products.','Finite-presentation proof dualizes correctly. The words comme dans 2.4 do not expressly repeat the direct-sum-to-product condition in the all-module sentence; it is required and should be made explicit.')
item(403,'Torsion functors and local cohomology detection','K21-01','9–12','233–398','Co-I-adic systems represent left-exact contravariant functors on finite I-torsion modules.')
claim(7,403,'Representation by co-I-adic systems','K21-01','9–11','233–316','systèmes inductifs co-I-adiques','On finite I-torsion modules, a left-exact contravariant T is equivalent to a compatible system Hn=T(A/I^(n+1)), with Hn=HomA(A/I^(n+1),Hm) for m≥n. Under exact countable filtered colimits, H=colim Hn represents T and is I-torsion.','Finite presentation plus exact filtered colimits commutes the relevant finite kernels with the colimit. Without such colimits the system formulation remains valid. Proposition 2.9 is only an editorial placeholder, so the preceding argument is its actual content.')
claim(8,403,'Lowest-degree vanishing of torsion cohomological functors','K21-01','11','318–350','Hi=lim Ti(A/I^(m+1))','For a bounded-below contravariant cohomological functor, vanishing below n is equivalent both to vanishing on a support-detecting family and to vanishing of the filtered colimits Hi below n. At the first possible degree Tn(M)=HomA(M,Hn).','Induction is valid: once lower degrees vanish, the next functor is left exact and claim007 applies. Exact countable filtered colimits are part of the statement.')
claim(9,403,'Associated primes from generic-component detection','K21-01','12','354–385','Ass T(M)=supp M ∩ S','If vanishing of a left-exact contravariant functor is determined by whether Supp M contains one of a selected family of irreducible components of V(I), then its representing torsion module H has Ass H precisely the selected generic points, and Ass T(M)=Supp M∩S.','Testing A/p proves Ass H=S. The final sentence repeats S where the argument needs Ass H, a local textual slip; the proof can be reconstructed without strengthening the hypothesis.')
claim(10,403,'Injectivity detected on finite torsion modules','K21-01','12–14','392–440','H injectif sss TH exact','For noetherian A and I-torsion H, exactness of Hom(-,H) on finite I-torsion modules implies A-injectivity. Consequently ΓI of an injective module is injective.','Baer plus Artin–Rees proves this: for N⊂M finite and u:N→H killed on I^nN, choose m with N∩I^mM⊂I^nN and extend through M/I^mM. The source prints N∩I^mN once but immediately uses the needed M in its displayed sequence.')
item(404,'Global ind-representability and a false recovery formula','K21-01','14','442–454','The categorical extension is valid with support; the displayed formula for H is not valid globally.')
claim(11,404,'Global left-exact functors are ind-representable','K21-01','14','442–454','F↦Hom(F,H); Ind(C)','For noetherian X, contravariant additive left-exact functors on CohY(X) to abelian groups are represented by quasi-coherent H supported on Y, through Ind(CohY(X)).','The ind-representability reasoning is sound with support retained. The source says all quasi-coherent modules in the last sentence although C still has support in Y; only Y-supported modules belong there.')
claim(12,404,'Global value on O does not recover the representing sheaf','K21-01','14','450','H ≃ lim T(OX/I^n)','The source asserts that the global representing sheaf is a colimit of the abelian groups T(OX/I^n).','False as a global recovery formula and ill-typed without a sheaf construction. For X=P¹, I=0, H=O(-1), T=Hom(-,H): all T(O)=0, while T(O(-1))=k. The representing sheaf is nonzero; local affine evaluation or the full ind-system is needed.','asserted in a generalization remark')
item(405,'Depth conditions for set-valued sheaves','K21-01;K21-02','16–22','K21-01:467–505; K21-02:1–133','Extension and uniqueness across a closed set are tested at all points of that set.')
claim(13,405,'P1 and P2 for sheaves of sets','K21-01','16','467–505','F → i*i*F injective (bijective)','For a sheaf of sets, P1 is uniqueness and P2 is unique extension from X\Y on every open. The local version uses the punctured localization at a point.','Definitions consistent; the marginal request to study surjectivity alone is a separate open flag. Surjectivity of a sheaf map is local lifting and is not global surjectivity on every open; do not merge those two possible formulations.','definitions with a marginal proposed addition')
claim(14,405,'Localization and constructible neighborhoods','K21-02','18–21','27–128','Γ(V(x),F(x)) ≃ colimW Γ(W∩V,F)','For a locally noetherian spectral space, sections on a localized open V(x) are the filtered colimit over neighborhoods W of x; constructible inclusions can be tested on the generizations of x.','Compactness of V(x) and finite shrinking of a finite cover supply the proof. The pages are out of proof order, but the finite-cover argument is present. No claim is made for arbitrary non-quasi-compact localizations.')
claim(15,405,'Pointwise criterion for extension of sheaves','K21-02','17–22','7–133','P1(P2) rel Y iff P1(P2) en chaque x∈Y','On a locally noetherian spectral space, P1 or P2 relative to Y holds iff it holds at each point of Y. These properties pass to smaller closed subsets and open restrictions.','Checked noetherian induction: extend or compare near a generic point of the remaining closed subset, then remove that neighborhood and invoke induction. Sheaf gluing is used. The initial sentence X affine is extraneous for an abstract spectral space; no affine scheme structure is needed.')
item(406,'Depth for fibred categories and torsors','K21-02','22–29','135–299','Faithfulness, full faithfulness, equivalence, and torsor extension are compared pointwise.')
claim(16,406,'P1 P2 P3 for fibred categories','K21-02','22–24','135–188','fidèle; pleinement fidèle; équivalence','The draft defines P1/P2/P3 by restriction of fibred categories, and uses Hom sheaves and pseudolimit localizations.','For a prestack the Hom presheaves are sheaves and localization is coherent. For an arbitrary fibred category Hom need not be a sheaf, so the stated sheaf reduction needs at least the prestack condition.','definitions and reductions')
claim(17,406,'Pointwise object extension needs descent','K21-02','25–27','193–255','à cause de l’unicité…la question est locale','The draft asserts P3 relative to Y iff P3 at every x∈Y for a fibred category, and glues objects over W and U.','False for arbitrary fibred categories. On the three-point spectral space with generic η and closed a,b, take U={η}; the discrete category has one object on each proper open and no object on X. Local punctured restrictions at a,b are equivalences, but global restriction is not essentially surjective. This is a prestack whose missing effective descent is exactly the gap. With a stack the noetherian induction works.','proof invokes unasserted effective descent')
claim(18,406,'Restriction stability for categorical depth','K21-02','25–26','207–240','ρ et ρ″ équivalences donc ρ′','If categorical restriction is an equivalence across Y on every open, it remains so across a smaller closed subset; the same cancellation holds for faithfulness/full faithfulness.','The triangle argument is valid independently of noetherianity and of effective descent; it does not repair claim017.')
claim(19,406,'Torsors and nonabelian local cohomology','K21-02','28–29','260–299','H⁰Y=H¹Y=0; H²Y sheaf of V↦H¹(V∩U,F)','For the stack of torsors under a sheaf of groups F, P1/P2 agree with the analogous sheaf conditions; P3 adds vanishing of the local torsor obstruction. Hom between torsors is locally a twist of F.','The torsor stack has effective descent, so the preceding gap is absent. H¹ and H² are pointed-set local obstruction objects here, not automatically abelian derived-functor groups. The order Cor10 before Prop9 in the scans is retained.')
problem(1,'Weak detection versus a categorical generator',[1,2],'système de générateurs','Use the explicitly defined nonzero-Hom detection and finite filtrations, not faithful Hom or quotient-generation.','The same term has a stronger common meaning; missing G in the typed definition matters.')
problem(2,'Existence and continuity in abstract representation',[4,5,6,7],'sous réserve d’existence; expliciter les énoncés duaux','Keep finite presentation, coproduct/product preservation, and exact filtered colimits distinct.','Several requested editorial expansions are mathematically necessary hypotheses.')
problem(3,'Global representing sheaf recovery',[11,12],'H≃lim T(OX/I^n)','Recover H from the full ind-object or local affine restrictions.','The global formula fails on P¹ with O(-1).')
problem(4,'Extension of sections under general localization',[13,14,15],'regarder aussi…surjective; Généraliser les lemmes','Distinguish sheaf epimorphism, surjectivity of every section map, and coherent inverse-limit localization.','Two explicit unfinished generalization flags; broadest formulation not specified.')
problem(5,'Effective descent in categorical depth',[16,17,18,19],'on trouve donc un objet…prolongeant ξ′','Require a stack (and prestack for Hom-sheaf reduction); torsors satisfy this.','The given proof glues objects, a property absent from a general fibred category.')
